function renderFiles(){const win=windows.get('files');if(!win)return;const queryFocused=document.activeElement?.id==='file-search',pos=queryFocused?document.activeElement.selectionStart:0;win.el.innerHTML=filesContent();renderFileRows();if(queryFocused){const input=$('#file-search');input.focus();try{input.setSelectionRange(pos,pos);}catch{}}}
