 if(target.dataset.appFavorite){toggleFavoriteApp(target.dataset.appFavorite);return;}
 if(target.dataset.searchScope){searchState.scope=target.dataset.searchScope;renderSearch(searchState.query);return;}
 if(target.dataset.searchResult!==undefined){searchState.index=Number(target.dataset.searchResult);openSearchResult();return;}
 if(target.dataset.searchFavorite){const file=fs.find(f=>f.id===target.dataset.searchFavorite);if(file){file.favorite=!file.favorite;renderSearchSelection();renderFileRows();}return;}
 if(target.dataset.action==='dismiss-search'){closePopup();return;}
 if(target.dataset.action==='clear-global-search'||target.dataset.action==='reset-search'){if(target.dataset.action==='reset-search')Object.assign(searchState,{scope:'all',kind:'all'});$('#global-search').value='';renderSearch('');$('#global-search').focus();return;}
 if(target.dataset.action==='open-search-result'||target.dataset.action==='reveal-search-result'){openSearchResult(target.dataset.action==='reveal-search-result');return;}
 if(target.dataset.action==='reset-app-filters'){Object.assign(appState,{query:'',filter:'all',category:'All categories'});renderApplications();return;}
 if(target.dataset.dismissModal!==undefined&&event.target===target){closeModal();return;}
 if(target.dataset.closePopup!==undefined){closePopup();return;}
 if(target.dataset.menu){if(popup?.name===target.dataset.menu)closePopup();else openMenu(target.dataset.menu,target);return;}
 if(target.dataset.popup){const name=target.dataset.popup;if(popup?.name===name){closePopup();return;}if(name==='control')showControl();else if(name==='calendar')showCalendar();else if(name==='network')showNetwork();else showPopup('battery','<h3>Power</h3><div class="notification"><strong>Connected to power</strong><p>Illustrative VM power state. This preview does not read host battery information.</p></div>',null,{className:'popover'});return;}
 if(target.dataset.open){if(target.dataset.folder){navigate(target.dataset.folder);return;}openApp(target.dataset.open);return;}
 if(target.dataset.folder){navigate(target.dataset.folder);return;}
 if(target.dataset.file){fileState.selected=target.dataset.file;$$('[data-file]').forEach(el=>{const selected=el.dataset.file===fileState.selected;el.classList.toggle('selected',selected);el.setAttribute(el.tagName==='TR'?'aria-selected':'aria-pressed',String(selected));});renderInspector();return;}
 if(target.dataset.fileView){fileState.view=target.dataset.fileView;renderFiles();return;}
 if(target.dataset.sort){fileState.descending=fileState.sort===target.dataset.sort?!fileState.descending:false;fileState.sort=target.dataset.sort;renderFileRows();return;}
 if(target.dataset.recent){closePopup();openFile(target.dataset.recent);return;}
 if(target.dataset.settingsPage){settingsPage=target.dataset.settingsPage;renderSettings();return;}
 if(target.dataset.note!==undefined){currentNote=Number(target.dataset.note);windows.get('notes').el.innerHTML=notesContent();return;}
 if(target.dataset.accent){prefs.accent=target.dataset.accent;applyPrefs();renderSettings();return;}
