 if(popup?.name==='search'&&(event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='w'){event.preventDefault();closePopup();return;}
 if(popup?.name==='search'&&(event.target.id==='global-search'||event.target.closest?.('[data-search-result]'))&&['ArrowDown','ArrowUp','Enter'].includes(event.key)){event.preventDefault();if(event.key==='Enter')openSearchResult(event.ctrlKey||event.metaKey);else if(searchState.items.length){searchState.index=(searchState.index+(event.key==='ArrowDown'?1:-1)+searchState.items.length)%searchState.items.length;renderSearchSelection();$('[data-search-result="'+searchState.index+'"]')?.scrollIntoView({block:'nearest'});}return;}
 if(popup?.name==='switcher'&&['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Enter'].includes(event.key)){event.preventDefault();if(event.key==='Enter'){openApp(popup.ids[switchIndex]);return;}switchIndex=(switchIndex+(['ArrowRight','ArrowDown'].includes(event.key)?1:-1)+popup.ids.length)%popup.ids.length;$$('.switcher button').forEach((el,i)=>el.classList.toggle('active',i===switchIndex));$('.switcher button.active').focus();return;}
 if(modal)return;
